import json
import re
import os

def parse_script(text: str):
    nodes = []
    edges = []

    # Split the text into blocks based on [NodeID]
    node_blocks = []
    current_node_id = None
    current_content = []

    for line in text.splitlines():
        line_stripped = line.strip()
        if not line_stripped:
            continue
        match = re.match(r'^\[(.*?)\]$', line_stripped)
        if match:
            if current_node_id:
                node_blocks.append((current_node_id, current_content))
            current_node_id = match.group(1)
            current_content = []
        else:
            current_content.append(line_stripped)
    if current_node_id:
        node_blocks.append((current_node_id, current_content))

    node_dict = {}

    for node_id, lines in node_blocks:
        node = {
            "id": node_id,
            "text": "",
            "speaker": "",
            "type": "line"
        }

        is_choice = any(re.match(r'^\d+\.', l) for l in lines)

        if is_choice:
            node["type"] = "choice"
            for l in lines:
                if '->' in l:
                    parts = l.split('->')
                    choice_part = parts[0].strip()
                    target = parts[1].strip()
                    edges.append({"from": node_id, "to": target, "text": choice_part})
        else:
            node["type"] = "line"
            if lines:
                line_content = lines[0]
                if '->' in line_content:
                    parts = line_content.split('->')
                    speaker_text = parts[0].strip()
                    target = parts[1].strip()

                    if ':' in speaker_text:
                        s_parts = speaker_text.split(':', 1)
                        node["speaker"] = s_parts[0].strip()
                        node["text"] = s_parts[1].strip()
                    else:
                        node["text"] = speaker_text

                    if target:
                        edges.append({"from": node_id, "to": target, "text": ""})
                else:
                    if ':' in line_content:
                        s_parts = line_content.split(':', 1)
                        node["speaker"] = s_parts[0].strip()
                        node["text"] = s_parts[1].strip()
                    else:
                        node["text"] = line_content

        nodes.append(node)
        node_dict[node_id] = node

    # Ensure all mentioned targets exist as nodes
    existing_ids = set(node_dict.keys())
    all_targets = set(edge["to"] for edge in edges if edge["to"])
    for target in all_targets:
        if target not in existing_ids:
            new_node = {
                "id": target,
                "text": "",
                "speaker": "",
                "type": "line"
            }
            nodes.append(new_node)
            existing_ids.add(target)

    return {"nodes": nodes, "edges": edges}

def main():
    if not os.path.exists('/app/script.txt'):
        return
    with open('/app/script.txt', 'r') as f:
        text = f.read()

    graph = parse_script(text)

    with open('/app/dialogue.json', 'w') as f:
        json.dump(graph, f, indent=2)

    with open('/app/dialogue.dot', 'w') as f:
        f.write('digraph dialogue {\n')
        for node in graph['nodes']:
            if node['speaker'] and node['text']:
                label = f"{node['speaker']}: {node['text']}"
            elif node['text']:
                label = node['text']
            else:
                label = node['id']
            label = label.replace('"', '\\"')
            f.write(f'  "{node["id"]}" [label="{label}", shape=box];\n')

        for edge in graph['edges']:
            edge_text = edge['text'].replace('"', '\\"')
            f.write(f'  "{edge["from"]}" -> "{edge["to"]}" [label="{edge_text}"];\n')
        f.write('}\n')

if __name__ == "__main__":
    main()
